{
  "steps": [
    {
      "action": "Obtain verifiable parental consent before processing any personal data of a child (a person under 18 years of age).",
      "citations": [
        {
          "act": "Digital Personal Data Protection Act, 2023",
          "section": "Section 9(1)"
        }
      ]
    },
    {
      "action": "Ensure that the consent provided by the parent or lawful guardian is free, specific, informed, unconditional, and unambiguous, given through a clear affirmative action.",
      "citations": [
        {
          "act": "Digital Personal Data Protection Act, 2023",
          "section": "Section 6(1)"
        }
      ]
    },
    {
      "action": "Refrain from any tracking or behavioral monitoring of children or targeted advertising directed at children.",
      "citations": [
        {
          "act": "Digital Personal Data Protection Act, 2023",
          "section": "Section 9(3)"
        }
      ]
    },
    {
      "action": "Implement age-gating mechanisms to verify the age of the user and the identity of the parent or guardian providing consent.",
      "citations": [
        {
          "act": "Digital Personal Data Protection Act, 2023",
          "section": "Section 9(2)"
        }
      ]
    }
  ]
}

{
  "steps": [
    {
      "action": "Obtain registration as a Consent Manager from the Data Fiduciary by fulfilling the eligibility criteria, including being a body corporate and having a valid registration with the Data Protection Board.",
      "citations": [
        {
          "act": "Digital Personal Data Protection Act, 2023",
          "section": "8(8)"
        }
      ]
    },
    {
      "action": "Establish a robust grievance redressal mechanism to address complaints from data principals regarding the management of their consent.",
      "citations": [
        {
          "act": "Digital Personal Data Protection Act, 2023",
          "section": "8(11)"
        }
      ]
    },
    {
      "action": "Ensure that consent is obtained, managed, and withdrawn by the data principal through an accessible, transparent, and interoperable platform.",
      "citations": [
        {
          "act": "Digital Personal Data Protection Act, 2023",
          "section": "8(9)"
        }
      ]
    },
    {
      "action": "Maintain accountability to the Data Fiduciary and act on behalf of the data principal, ensuring that the consent provided is free, specific, informed, unconditional, and unambiguous.",
      "citations": [
        {
          "act": "Digital Personal Data Protection Act, 2023",
          "section": "6(1)"
        }
      ]
    },
    {
      "action": "Implement technical and organizational measures to ensure the security of the consent data and prevent unauthorized access or processing.",
      "citations": [
        {
          "act": "Digital Personal Data Protection Act, 2023",
          "section": "8(5)"
        }
      ]
    }
  ]
}

{
  "steps": [
    {
      "action": "Implement reasonable security safeguards to prevent personal data breaches, which include technical and organizational measures appropriate to the nature, scope, context, and purpose of processing.",
      "citations": [
