    {
      "action": "Maintain a comprehensive documented information security program and information security policies that contain managerial, technical, operational, and physical security control measures.",
      "citations": [
        {
          "act": "Information Technology (Reasonable Security Practices and Procedures and Sensitive Personal Data or Information) Rules, 2011",
          "section": "8(1)"
        }
      ]
    },
    {
      "action": "Conduct regular security audits by an independent auditor at least once a year or when there is a significant upgrade of the process and computer resource.",
      "citations": [
        {
          "act": "Information Technology (Reasonable Security Practices and Procedures and Sensitive Personal Data or Information) Rules, 2011",
          "section": "8(4)"
        }
      ]
    },
    {
